referenceSolutions.javascript:
export function solve(value, keys) {
  const omitted = new Set(keys);
  const walk = (x) =>
    Array.isArray(x)
      ? x.map(walk)
      : x !== null && typeof x === "object"
        ? Object.fromEntries(
            Object.entries(x)
              .filter(([k]) => !omitted.has(k))
              .map(([k, v]) => [k, walk(v)]),
          )
        : x;
  return walk(value);
}

